const fs = require('fs');
const path = require('path');
const vm = require('vm');
const root = path.resolve(__dirname, '..');
function load(rel){
  const filename = path.join(root, rel);
  vm.runInThisContext(fs.readFileSync(filename,'utf8'), {filename});
}
function write(rel, name, value){
  const out = path.join(root, rel);
  fs.writeFileSync(out, `/* generated by scripts/bundle_runtime.js */\nwindow.${name}=${JSON.stringify(value)};\n`);
}

function csvCell(v){
  const s = Array.isArray(v) ? v.join(' | ') : (v ?? '').toString();
  return /[",\n]/.test(s) ? '"'+s.replace(/"/g,'""')+'"' : s;
}
function writeCsv(rel, headers, rows){
  const out=path.join(root,rel);
  const text=[headers.join(','),...rows.map(r=>headers.map(h=>csvCell(r[h])).join(','))].join('\n')+'\n';
  fs.writeFileSync(out,text,'utf8');
}

global.window = {};
for(const f of ['data/data.js','data/extra.js','data/v05.js','data/v060.js','data/v061.js','data/v068.js']) load(f);
write('data/data_bundle.js','DOT_DATA',window.DOT_DATA);

const catalogHeaders=['string','round','status','type','entity','group','geography','themes','contention_count','strange','city','placeholder','provenance','sources'];
writeCsv('data/explorer_catalog.csv', catalogHeaders, (window.DOT_DATA.explorer||[]).map(r=>({
  string:r.string,round:r.round,status:r.status,type:r.type,entity:r.entity,group:r.group,geography:r.geography,themes:r.themes||[],contention_count:r.contentionCount??'',strange:r.strange?'yes':'no',city:r.city?'yes':'no',placeholder:r.placeholder?'yes':'no',provenance:r.provenanceKey?(r.provenanceKey+(r.provenanceDate?' · '+r.provenanceDate:'')):'',sources:r.source||[]
})));
const eventHeaders=['string','period','status','type','entity','geography','current','provenance','sources'];
const eventRows=[];
for(const r of (window.DOT_DATA.explorer||[])){for(const e of (r.events||[])){eventRows.push({string:r.string,period:e.period,status:e.status,type:e.type,entity:e.entity,geography:e.geography,current:e.current?'yes':'no',provenance:e.provenanceKey?(e.provenanceKey+(e.provenanceDate?' · '+e.provenanceDate:'')):'',sources:e.source||[]})}}
writeCsv('data/explorer_events.csv',eventHeaders,eventRows);
const sourceHeaders=['label','url','role'];
writeCsv('data/sources.csv',sourceHeaders,(window.DOT_DATA.sources||[]).map(s=>({label:s[0]||'',url:s[1]||'',role:s[2]||''})));

global.window = {};
for(const f of ['data/i18n.js','data/i18n_extra.js','data/i18n_v05.js','data/i18n_v058.js','data/i18n_v060.js','data/i18n_v061.js','data/i18n_v062.js','data/i18n_v065.js','data/i18n_v068.js']) load(f);
write('data/i18n_bundle.js','DOT_I18N',window.DOT_I18N);

console.log('Generated data/data_bundle.js and data/i18n_bundle.js');
